import{_ as s,h as i,i as e,c as n,v as l,p as o,x as r,m as H,e as h,S as m}from"./chunks/framework.Dvtg8yj2.js";const u=JSON.parse('{"title":"多轴偏好：有用/诚实/无害","description":"","frontmatter":{"title":"多轴偏好：有用/诚实/无害","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/hhh-axes.md","filePath":"llm/hhh-axes.md","lastUpdated":1788454257000}'),p={name:"llm/hhh-axes.md"};function A(E,a,d,c,_,f){const t=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="多轴偏好-有用-诚实-无害" tabindex="-1">多轴偏好：有用/诚实/无害 <a class="header-anchor" href="#多轴偏好-有用-诚实-无害" aria-label="Permalink to &quot;多轴偏好：有用/诚实/无害&quot;">​</a></h1><div class="epigraph"><p>有用、诚实、无害不是同一条分数的三个别名；它们经常互相卡住，必须分开写进指南、比较协议和评测表，而不能指望一个标量自己排好序。</p><footer>—— Askell et al., A General Language Assistant as a Laboratory for Alignment, 2021；Bai et al., Training a Helpful and Harmless Assistant with RLHF, 2022</footer></div><p>Askell 等人把对齐实验室的目标收成三个轴：有用（Helpful）、诚实（Honest）、无害（Harmless），合称 HHH。有用要求模型按用户意图做事、在含糊时追问；诚实要求不编造、不确定时说不确定、不隐瞒已知限制；无害要求不协助造成伤害、不无故冒犯。Bai 等人随后的 HH-RLHF 把其中两条——有用与无害——做成可训练的成对偏好，并公开了 Anthropic 的 HH 比较集。本篇写多轴为什么不能压成一个 <a href="/llm/reward-model">奖励模型</a> 标量、比较协议怎么拆、以及评测必须成对看哪些曲线。诚实轴与引用幻觉见 <a href="/llm/honesty-citations">虚构引用</a>；无害推得过猛见 <a href="/llm/over-refusal">过度拒绝</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单一偏好问题是：标注员在「哪一条更好」里当场权衡三件事，残差被模型当成一种质量。开放问答里更长、更会道歉、更会附和用户的回答，常常同时抬高「有用」的表面分、压低诚实与无害的真实符合度。Askell 的实验室设定已经指出冲突：用户要危险帮助时，有用与无害相反；用户持有错误前提时，有用（顺着说）与诚实（纠正）相反；拒答过宽则无害上升、有用下降。HH-RLHF 的经验是：把有用比较与无害比较分成两套数据、两套偏好模型，冲突才会变成可调的组合规则，而不是藏在标注方差里。</p><p>把三轴写成口号再交给众包，得到的是平均人格，不是可审计政策。政策必须先回答：哪一类请求必须拒、哪一类必须答、不确定时默认偏向哪一轴。没有这张表，HHH 只是三个英文词。</p><h3 id="三轴冲突不是标注噪声" tabindex="-1">三轴冲突不是标注噪声 <a class="header-anchor" href="#三轴冲突不是标注噪声" aria-label="Permalink to &quot;三轴冲突不是标注噪声&quot;">​</a></h3><p>噪声是同一轴上两人看法不同；冲突是同一条 \\((x,y)\\) 在两轴上的序相反。用户问「把这段合同改得对我更有利」：有用轴可能偏好改稿，无害/诚实轴可能偏好指出这不是法律意见并拒绝伪造条款。若只采一条总序，赢的往往是「先免责再尽量改」的折中腔，两边都不满意。正确做法是允许同一对在不同轴上标出相反的胜者，下游用分头 \\(r_{\\mathrm{H}},r_{\\mathrm{Hon}},r_{\\mathrm{HH}}\\) 或词典序（先过无害阈值，再比有用，诚实用独立探针约束）。Llama 2 把有用与安全分头，是同一工程判断。</p><p><span class="marginnote">Askell 2021 的 HHH 是评测与写作指南的坐标系；Bai 2022 的 HH-RLHF 是把 H 与 Harmless 做成偏好学习的数据与 RL 流程。不要把实验室论文里的定性轴，直接写成 HH 数据集已经覆盖了诚实。HH 公开集对「无害 vs 有用」更密，对「引用是否真实」更稀。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>收集：每个提示至少服务一个主轴。有用集来自真实或仿真的助手请求，比较「完成意图的质量」；无害集来自红队与政策类别，比较「拒、改写、给替代」是否符合书面政策；诚实集来自可知真值或可知无知的题（事实、引用、能力边界），比较「对、说不知道、给出处」是否优于流畅编造。指南要写清平局：两条都无害但一条更啰嗦，有用轴可以分胜负，无害轴应标平。Bai 等人强调无害数据需要对抗性提示，因为清洁的危害关键词测不到包装后的失败。</p><p>建模：分头奖励或分头比较，推理时再组合。组合不是唯一的。阈值门：无害分低于 \\(\\tau\\) 则走拒答模板，否则最大化有用。加权和：\\(r=\\lambda_{\\mathrm{H}} r_{\\mathrm{H}}+\\lambda_{\\mathrm{HH}} r_{\\mathrm{HH}}\\)，权是产品超参，必须在过拒绝曲线上扫。诚实很少适合直接加进同一 PPO 标量，因为它的失败（虚构文献）在成对「看起来更专业」里往往赢；更稳的是独立评测门加检索约束，见诚实篇。</p>',12)),(e(),o(m,null,{default:r(()=>[h(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20POL%5B%22%E4%B9%A6%E9%9D%A2%E6%94%BF%E7%AD%96%EF%BC%9A%E6%8B%92%20%2F%20%E5%BA%94%20%2F%20%E6%BE%84%E6%B8%85%22%5D%20--%3E%20H%5B%22%E6%9C%89%E7%94%A8%E6%AF%94%E8%BE%83%22%5D%0A%20%20POL%20--%3E%20HH%5B%22%E6%97%A0%E5%AE%B3%E6%AF%94%E8%BE%83%22%5D%0A%20%20POL%20--%3E%20HON%5B%22%E8%AF%9A%E5%AE%9E%E6%8E%A2%E9%92%88%E4%B8%8E%E5%BC%95%E7%94%A8%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20H%20--%3E%20RH%5B%22r_helpful%22%5D%0A%20%20HH%20--%3E%20RS%5B%22r_harmless%22%5D%0A%20%20RH%20--%3E%20MIX%5B%22%E7%BB%84%E5%90%88%EF%BC%9A%E9%98%88%E5%80%BC%E9%97%A8%E6%88%96%E5%8A%A0%E6%9D%83%22%5D%0A%20%20RS%20--%3E%20MIX%0A%20%20HON%20--%3E%20GATE%5B%22%E7%8B%AC%E7%AB%8B%E8%AF%9A%E5%AE%9E%E9%97%A8%22%5D%0A%20%20MIX%20--%3E%20PI%5B%22%E7%AD%96%E7%95%A5%22%5D%0A%20%20GATE%20--%3E%20PI%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[H(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>评测表最少四列：有用（指令遵循、人工或 Arena 类）、无害（政策类别上的配合率，只用公开套件接口）、过拒绝（表面敏感但应回答）、诚实（已知题准确率、虚构引用率、拒答是否承认无知）。只报无害下降或只报有用上升，都会选出单轴过拟合的检查点。Askell 的实验室写法是把三条行为描述给评测员；工业上要把描述收成可重复的题集，否则「HHH 分」不可比。</p><h3 id="指南里的词典序与加权" tabindex="-1">指南里的词典序与加权 <a class="header-anchor" href="#指南里的词典序与加权" aria-label="Permalink to &quot;指南里的词典序与加权&quot;">​</a></h3><p>标注指南应显式规定冲突时的优先级。常见词典序：无害优先于有用，诚实优先于「听起来有用」。这不是道德哲学声明，而是为了降低标注方差：没有词典序，有的标注员会完成危险请求并标赢，有的会拒并标赢，<a href="/llm/bradley-terry">BT 模型</a> 会拟合噪声。加权用于轴内：有用轴上完整性高于文采；诚实轴上正确高于详尽。指南外的美学不要偷偷进比较，否则 HHH 会被文风吞掉。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>成对数据把轴投影到胜负。若比较者在无害题上仍按「谁答得全」选，无害头会学成有用头的副本。HH-RLHF 把两套比较分开，等于把投影矩阵写成块对角，冲突留给组合层。RL 或 <a href="/llm/dpo">DPO</a> 沿组合后的标量上升：\\(\\lambda_{\\mathrm{HH}}\\) 过大，策略进入过拒绝；\\(\\lambda_{\\mathrm{H}}\\) 过大，策略在边界题上配合。KL 只限制走多远，不告诉你走的是哪一轴。因此分头不是多此一举，是让「走哪一轴」成为可调参数。</p><p>诚实更难进同一机制。虚构但带文献格式的回答，在有用比较里常赢，因为信息密度的表面更高。无害比较也不惩罚编造论文，除非指南写了「不得伪造出处」。于是三轴里诚实最容易被另外两轴的梯度盖掉。机制上的补救是：诚实不靠同一 \\(r\\) 的第十三项权重，而靠可检查的约束（检索到的才允许引用）和单独探针（见诚实篇）。</p><p><span class="marginnote">「更无害」在比较里经常长得像更长的道歉。无害头会和 <a href="/llm/length-bias-rm">长度偏置</a> 耦合。长度匹配的比较、或对拒答长度设上限，是无害轴的数据补丁，不是 HHH 定义自带的。</span></p><h3 id="红队只覆盖无害轴的一部分" tabindex="-1">红队只覆盖无害轴的一部分 <a class="header-anchor" href="#红队只覆盖无害轴的一部分" aria-label="Permalink to &quot;红队只覆盖无害轴的一部分&quot;">​</a></h3><p>Bai 等人的无害数据依赖人写对抗提示。这提高了无害头在「像红队的题面」上的分辨率，但不自动提高诚实或有用。把红队题拿去当有用比较的 \\(x\\)，会污染有用头。三轴要三套提示分布：日常助手、政策类别与对抗包装、可知真值。共享提示可以，但标签必须按轴分列，不能一条总序复制三遍。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>HHH 不是完备基。公平、隐私、版权、工具调用的副作用，常常单列政策，不要硬塞进无害。多语言上，英语无害模板混进其他语言有用数据，会出现只在英语拒、在其他语言配合或乱拒。轴的定义要按语言与产品线版本化。</p><p>众包能标有用，未必能标无害与诚实，见 <a href="/llm/expert-vs-crowd">专家 vs 众包</a>。无害需要政策训练与抽检；诚实需要答案键或检索。用同一批标注员三轴全标，是成本上的假省：方差会变成「看起来像助手」。Constitutional AI 把无害比较改成原则驱动的 <a href="/llm/aif-as-preference">AI 反馈</a>，减轻人直接看有害内容，但不取消书面原则，也不自动覆盖诚实。</p><p><span class="marginnote">产品上不要对外承诺「已优化 HHH」而不给四列表。HHH 是坐标系。坐标没有刻度时，营销句和训练目标不是同一对象。</span></p><p>公开 HH 数据有用，但政策不是你的政策。用 HH 训无害头再在自己的类别上测，会有盲区。应把 HH 当预训练式的偏好先验，用自己的政策比较做适应，并报告域外无害与过拒绝。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Askell 的 HHH 把对齐拆成有用、诚实、无害三轴；轴间冲突是结构问题，不是标注噪声。</li><li>Bai 的 HH-RLHF 把有用与无害做成分头偏好；诚实通常需要独立探针与可检查约束。</li><li>比较协议按轴分列，冲突用词典序或阈值门处理，再扫组合权重。</li><li>评测必须同时看有用、无害配合率、过拒绝、诚实，单列会选出单轴过拟合。</li><li>无害比较易与长度、道歉腔耦合；有用比较易奖励虚构的详尽。</li><li>出处：Askell et al., <em>A General Language Assistant as a Laboratory for Alignment</em>, 2021；Bai et al., <em>Training a Helpful and Harmless Assistant with Reinforcement Learning from Human Feedback</em>, 2022。</li></ul>',16))])}const b=s(p,[["render",A]]);export{u as __pageData,b as default};
